// Input configuration for the workflow
const config = {
  source_url: $input.first()?.json?.source_url || 'https://feeds.bbci.co.uk/news/rss.xml',
  max_headlines: $input.first()?.json?.max_headlines || 5,
  request_id: `VER-${Date.now().toString(36).toUpperCase()}`
};

return [{ json: config }];

// Extract headlines for processing
const response = $input.first().json;
const headlines = response.headlines || [];
const config = {
  source_url: response.source_url,
  source_type: response.source_type,
  fetch_time_ms: response.fetch_time_ms
};

// Return each headline as a separate item
return headlines.map((headline, index) => ({
  json: {
    index,
    headline,
    config
  }
}));

// Combine headline info with extracted content
const headline = $('Split Headlines').item.json.headline;
const config = $('Split Headlines').item.json.config;
const content = $input.item.json;

return {
  json: {
    headline,
    config,
    content: content.content,
    word_count: content.word_count
  }
};

// Combine all analysis results
const headline = $('Merge Content').item.json.headline;
const content = $('Merge Content').item.json.content;
const sources = $('Find Alternative Sources').item.json;
const claims = $('Extract Claims').item.json;

return {
  json: {
    headline,
    content,
    alternative_sources: sources.sources_found || [],
    claims: claims.claims || [],
    search_queries: sources.search_queries_used || []
  }
};

// Aggregate all classification results
const results = $input.all().map(item => item.json);

// Calculate statistics
const stats = {
  total: results.length,
  likely_real: results.filter(r => r.verdict === 'LIKELY_REAL').length,
  likely_fake: results.filter(r => r.verdict === 'LIKELY_FAKE').length,
  uncertain: results.filter(r => r.verdict === 'UNCERTAIN').length,
  avg_confidence: results.length > 0 
    ? Math.round(results.reduce((sum, r) => sum + r.confidence, 0) / results.length * 100) 
    : 0
};

// Get config from first item
const firstConfig = $('Split Headlines').first()?.json?.config || {};

return [{
  json: {
    request_id: $('Configure Request').first().json.request_id,
    source_url: firstConfig.source_url,
    source_type: firstConfig.source_type,
    headlines_analyzed: results.length,
    statistics: stats,
    results: results.map(r => ({
      headline: r.headline,
      verdict: r.verdict,
      confidence: r.confidence,
      supporting_sources: r.supporting_sources,
      contradicting_sources: r.contradicting_sources,
      summary: r.summary,
      factors: r.factors
    })),
    timestamp: new Date().toISOString()
  }
}];

// Format final report
const data = $input.first().json;

const separator = '='.repeat(70);
const subseparator = '-'.repeat(40);

let report = `\n${separator}\n  NEWS VERIFICATION REPORT\n${separator}\n\n`;
report += `Request ID: ${data.request_id}\n`;
report += `Source: ${data.source_url}\n`;
report += `Headlines Analyzed: ${data.headlines_analyzed}\n`;
report += `Timestamp: ${data.timestamp}\n\n`;

report += `${subseparator}\nOVERALL STATISTICS\n${subseparator}\n`;
report += `  Likely Real:    ${data.statistics.likely_real}\n`;
report += `  Likely Fake:    ${data.statistics.likely_fake}\n`;
report += `  Uncertain:      ${data.statistics.uncertain}\n`;
report += `  Avg Confidence: ${data.statistics.avg_confidence}%\n\n`;

report += `${subseparator}\nDETAILED CLASSIFICATIONS\n${subseparator}\n\n`;

data.results.forEach((r, i) => {
  const verdictIcon = r.verdict === 'LIKELY_REAL' ? '✓' : 
                      r.verdict === 'LIKELY_FAKE' ? '✗' : '?';
  report += `[${i + 1}] ${r.headline.substring(0, 60)}...\n`;
  report += `    Verdict: ${verdictIcon} ${r.verdict}\n`;
  report += `    Confidence: ${Math.round(r.confidence * 100)}%\n`;
  report += `    Supporting: ${r.supporting_sources} | Contradicting: ${r.contradicting_sources}\n`;
  report += `    Summary: ${r.summary}\n\n`;
});

report += separator;

return [{ json: { ...data, formatted_report: report } }];
